// Flatten Meta's insights payload into columns.
const post = $('Posts to measure').item.json;
const m = {};
for (const d of ($json.data ?? [])) m[d.name] = d.values?.[0]?.value ?? d.total_value?.value ?? 0;
return [{ json: { post_id: post.id, views: m.views ?? 0, likes: m.likes ?? 0,
  replies: m.replies ?? 0, reposts: m.reposts ?? 0, quotes: m.quotes ?? 0 } }];

parameters.query:
INSERT INTO post_metrics (post_id, age_hours, views, likes, replies, reposts, quotes)
SELECT $1, EXTRACT(EPOCH FROM (now()-published_at))/3600, $2,$3,$4,$5,$6
  FROM posts WHERE id=$1;

